"""Migrated Meridian CRM 4.2 case_lifecycle workflow transitions."""

from __future__ import annotations

from typing import Any


def _field(record: dict, name: str) -> Any:
    """Return a VRL field value; absent fields read as the empty string."""
    return record.get(name, "")


def _nvl(value: Any, default: str) -> Any:
    """VRL NVL treats missing/empty values as null."""
    return default if value == "" or value is None else value


_TRANSITIONS = (
    {
        "from": "N",
        "to": "A",
        "event": "assign",
        "guard": lambda record: _field(record, "OWNER_UID") != "",
        "actions": (("audit", "CASE_ASSIGN"),),
    },
    {
        "from": "N",
        "to": "A",
        "event": "auto_escalate",
        "guard": None,
        "actions": (
            ("set", "ESC_FLG", "Y"),
            ("set_expr", "SEV_CD", lambda record: _nvl(_field(record, "SEV_CD"), "3")),
            ("audit", "CASE_ESC"),
            ("notify", "escalation"),
        ),
    },
    {
        "from": "A",
        "to": "A",
        "event": "auto_escalate",
        "guard": lambda record: _field(record, "ESC_FLG") != "Y",
        "actions": (
            ("set", "ESC_FLG", "Y"),
            ("audit", "CASE_ESC"),
            ("notify", "escalation"),
        ),
    },
    {
        "from": "A",
        "to": "P",
        "event": "await_customer",
        "guard": None,
        "actions": (("audit", "CASE_PEND"),),
    },
    {
        "from": "P",
        "to": "A",
        "event": "customer_reply",
        "guard": None,
        "actions": (),
    },
    {
        "from": "A",
        "to": "R",
        "event": "resolve",
        "guard": lambda record: _field(record, "RES_DT") != "00000000",
        "actions": (("audit", "CASE_RES"),),
    },
    {
        "from": "R",
        "to": "X",
        "event": "close",
        "guard": None,
        "actions": (("audit", "CASE_CLOSE"),),
    },
    {
        "from": "R",
        "to": "A",
        "event": "reopen",
        "guard": None,
        "actions": (
            ("set", "RES_DT", "00000000"),
            ("audit", "CASE_REOPEN"),
        ),
    },
)


def fire(state: str, event: str, record: dict) -> dict:
    """Dispatch one explicit case_lifecycle event using legacy document order."""
    result_record = dict(record)

    for transition in _TRANSITIONS:
        if transition["from"] != state or transition["event"] != event:
            continue

        guard = transition["guard"]
        if guard is not None and not guard(result_record):
            continue

        audits: list[str] = []
        notifies: list[str] = []

        for action in transition["actions"]:
            action_type = action[0]
            if action_type == "set":
                result_record[action[1]] = action[2]
            elif action_type == "set_expr":
                result_record[action[1]] = action[2](result_record)
            elif action_type == "audit":
                audits.append(action[1])
            elif action_type == "notify":
                notifies.append(action[1])

        return {
            "state": transition["to"],
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
